  if (m.containsKey('array')) {
    if (v is! List) return '$path: expected array';
    final max = m['maxItems'];
    if (max is int && v.length > max) return '$path: more than $max items';
    for (var i = 0; i < v.length; i++) {
      final e = _check(v[i], m['array'], '$path[$i]');
      if (e != null) return e;
    }
    return null;
