  if (m.containsKey('map')) {
    if (v is! Map) return '$path: expected object';
    for (final entry in v.entries) {
      if (entry.key is! String) return '$path: expected string keys';
      final e = _check(entry.value, m['map'], '$path.${entry.key}');
      if (e != null) return e;
    }
    return null;
  }
