      if (optional) continue;
      return '$path.$name: missing';
    }
    final e = _check(v[name], entry.value, '$path.$name');
    if (e != null) return e;
  }
  if (!additional) {
    for (final k in v.keys) {
      if (!known.contains(k)) return '$path.$k: unexpected field';
