  if (island != null && !(s['islands']! as List).contains(island.name)) {
    return '\$.t: $t is not for the ${island.name} island';
  }
  return _checkObject(value, (s['fields']! as Map).cast<String, Object?>(), false, r'$', const {'v', 't'});
}

