/// Base of every protocol message. Parse with [IslandMessage.parse] / [IslandMessage.tryParse].
sealed class IslandMessage {
  const IslandMessage();

  /// The `t` value.
  String get t;
  MessageDirection get direction;
  Set<IslandKind> get islands;

  /// The wire object, including `v` and `t`.
