    if (error != null) throw FormatException('Invalid island message: $error');
    final m = (json! as Map).cast<String, Object?>();
    switch (m['t']) {
      case "init":
        return InitMessage.fromJson(m);
      case "module.load":
        return ModuleLoadMessage.fromJson(m);
      case "media.put":
        return MediaPutMessage.fromJson(m);
      case "question.show":
        return QuestionShowMessage.fromJson(m);
      case "state.patch":
        return StatePatchMessage.fromJson(m);
      case "view.set":
        return ViewSetMessage.fromJson(m);
      case "annot.apply":
        return AnnotApplyMessage.fromJson(m);
      case "selection.get":
        return SelectionGetMessage.fromJson(m);
      case "focus.release":
        return FocusReleaseMessage.fromJson(m);
      case "ready":
        return ReadyMessage.fromJson(m);
      case "module.loaded":
        return ModuleLoadedMessage.fromJson(m);
      case "question.shown":
        return QuestionShownMessage.fromJson(m);
      case "answer.choose":
        return AnswerChooseMessage.fromJson(m);
      case "answer.input":
        return AnswerInputMessage.fromJson(m);
      case "answer.eliminate":
        return AnswerEliminateMessage.fromJson(m);
      case "flag.toggle":
        return FlagToggleMessage.fromJson(m);
      case "eliminator.toggle":
        return EliminatorToggleMessage.fromJson(m);
      case "selection":
        return SelectionMessage.fromJson(m);
      case "selection.clear":
        return SelectionClearMessage.fromJson(m);
      case "annot.click":
        return AnnotClickMessage.fromJson(m);
      case "annot.changed":
        return AnnotChangedMessage.fromJson(m);
      case "selection.current":
        return SelectionCurrentMessage.fromJson(m);
      case "key":
        return KeyMessage.fromJson(m);
      case "focus":
        return FocusMessage.fromJson(m);
      case "split.changed":
        return SplitChangedMessage.fromJson(m);
      case "error":
        return ErrorMessage.fromJson(m);
      case "desmos.init":
        return DesmosInitMessage.fromJson(m);
      case "desmos.mode":
        return DesmosModeMessage.fromJson(m);
      case "desmos.getState":
        return DesmosGetStateMessage.fromJson(m);
      case "desmos.ready":
        return DesmosReadyMessage.fromJson(m);
      case "desmos.failed":
        return DesmosFailedMessage.fromJson(m);
      case "desmos.changed":
        return DesmosChangedMessage.fromJson(m);
      case "desmos.state":
        return DesmosStateMessage.fromJson(m);
    }
    throw FormatException('Unknown island message type ${m["t"]}');
  }

  /// [parse], or null when the message does not match the schema (drop it).
  static IslandMessage? tryParse(Object? json, {MessageDirection? direction, IslandKind? island}) {
    if (validateIslandMessage(json, direction: direction, island: island) != null) return null;
    return parse(json, direction: direction, island: island);
