  /// Decode a JSON string from `WebMessageReceived`, or null when invalid.
  static IslandMessage? tryDecode(String text, {MessageDirection? direction, IslandKind? island}) {
    Object? json;
    try {
      json = jsonDecode(text);
    } on FormatException {
      return null;
    }
    return tryParse(json, direction: direction, island: island);
  }
}

